<script setup lang="ts">
import {ArrowUpRight,Coins,Landmark,RefreshCw,ShieldCheck,WalletCards} from 'lucide-vue-next';
import type {CryptoChain} from '../lib/cryptoPayments';
import {portfolioAmount,portfolioStatus,type PortfolioSnapshot} from '../lib/cryptoPortfolio';
import {stamp} from '../lib/commerce';
import {t} from '../i18n';
defineProps<{chains:CryptoChain[];summaries:Record<string,PortfolioSnapshot>;errors:Record<string,string>;selectedChain:string;walletName:string;loading:boolean;writable:boolean;busy:boolean}>();
const emit=defineEmits<{chain:[id:string];gas:[];withdraw:[]}>();
const statusLabels={loading:'等待链上查询',refreshing:'正在更新',stale:'上次成功快照',partial:'部分地址待核对',failed:'暂无成功快照',ready:'余额已更新'};
</script>
<template>
 <section class="wallet-portfolio-overview">
  <article class="wallet-overview-hero">
   <div><span class="wallet-eyebrow"><WalletCards :size="16"/>{{t('钱包资产总览')}}</span><h4>{{walletName}}</h4><p>{{t('所有历史收款地址的余额按网络和币种分别汇总。')}}</p></div>
   <div class="wallet-hero-actions"><button type="button" @click="emit('gas')"><Landmark :size="16"/>{{t('充值 Gas')}}</button><button type="button" class="primary" :disabled="!writable||busy" @click="emit('withdraw')"><ArrowUpRight :size="16"/>{{t('归集提现')}}</button></div>
  </article>
  <p class="wallet-overview-caption">{{t('资产数量直接来自链上，不合并不同网络余额，也不按美元估值。')}}</p>
  <div class="wallet-network-assets">
   <article v-for="network in chains" :key="network.id" class="wallet-network-card" :class="{selected:network.id===selectedChain}">
    <header><button type="button" class="wallet-network-title" :disabled="busy" @click="emit('chain',network.id)"><span class="network-coin">{{network.native_symbol.slice(0,1)}}</span><span><strong>{{network.name}}</strong><small>{{network.native_symbol}} · {{t('链上余额')}}</small></span></button><span class="wallet-data-state" :class="portfolioStatus(summaries[network.id],errors[network.id])"><RefreshCw v-if="summaries[network.id]?.refreshing||(loading&&!summaries[network.id])" :size="13" class="spin"/><ShieldCheck v-else-if="portfolioStatus(summaries[network.id],errors[network.id])==='ready'" :size="13"/>{{t(statusLabels[portfolioStatus(summaries[network.id],errors[network.id])])}}</span></header>
    <dl class="network-native"><div><dt>{{t('收款地址手续费币')}}</dt><dd>{{portfolioAmount(summaries[network.id]?.native_balance_atoms)}} <small>{{network.native_symbol}}</small></dd></div><div><dt>{{t('Gas 资金地址')}}</dt><dd>{{portfolioAmount(summaries[network.id]?.funding_balance_atoms)}} <small>{{network.native_symbol}}</small></dd></div></dl>
    <div class="wallet-token-list"><div v-for="asset in summaries[network.id]?.tokens||[]" :key="asset.asset_id" class="wallet-token"><span class="token-coin"><Coins :size="17"/></span><div><strong>{{asset.symbol}}</strong><small>{{network.name}}</small></div><b>{{portfolioAmount(asset.balance_atoms,asset.decimals)}}</b></div><p v-if="summaries[network.id]&&!summaries[network.id].tokens.length">{{t('此网络尚未配置收款币种')}}</p><div v-if="!summaries[network.id]" class="wallet-token-placeholder">{{t('正在读取此网络的资产…')}}</div></div>
    <footer><span>{{t('有余额地址')}} <strong>{{summaries[network.id]?.funded_addresses??'—'}}</strong> / {{summaries[network.id]?.total_addresses??'—'}}</span><span v-if="summaries[network.id]?.checked_at">{{t('最近查询')}} {{stamp(summaries[network.id]!.checked_at)}}</span></footer>
    <p v-if="errors[network.id]||summaries[network.id]?.errors?.length" class="wallet-network-warning" role="status">{{t('查询未完成，未知余额不会显示为零。')}} {{t(errors[network.id]||summaries[network.id]?.errors[0]||'')}}</p>
   </article>
  </div>
 </section>
</template>
